import { Flow, wfa, trigger } from '@servicenow/sdk/automation'

// Flow that defines a monthly scheduled trigger on a specific day and time.

Flow(
    {
        $id: Now.ID['flow_trigger_scheduled_monthly'],
        name: 'Flow - Trigger Scheduled Monthly',
        description: 'Flow used by tests to validate monthly scheduled trigger configuration.',
        runAs: 'system',
        runWithRoles: [],
        flowPriority: 'MEDIUM',
    },
    wfa.trigger(
        trigger.scheduled.monthly,
        { $id: Now.ID['trigger_scheduled_monthly'], annotation: 'Monthly scheduled trigger on day 5 at 11:00:00' },
        {
            day_of_month: 5,
            time: Time({ hours: 11, minutes: 0, seconds: 0 }),
        }
    ),
    () => {
        // Empty body; this test focuses on scheduled trigger configuration only
    }
)
